235	export async function registerNewMember(values: z.infer<typeof registerSchema>) {
236	    const supabase = await createClient();
237	    const supabaseAdmin = await createAdminClient();
238	    const { data: { user } } = await supabase.auth.getUser();
239	
240	    if (!user) {
241	        return { error: '登録するにはログインする必要があります。' };
242	    }
243	    
244	    const { data: existingMember } = await supabase
245	        .from('members')
246	        .select('supabase_auth_user_id')
247	        .eq('supabase_auth_user_id', user.id)
248	        .is('deleted_at', null)
249	        .single();
250	
251	    if (existingMember) {
252	        return { error: 'このユーザーは既に登録済みです。' };
253	    }
254	
255	    const parsedData = registerSchema.safeParse(values);
256	    if (!parsedData.success) {
257	        console.error("Invalid registration data:", parsedData.error.flatten());
258	        const firstError = parsedData.error.flatten().fieldErrors;
259	        const errorMessage = Object.values(firstError)[0]?.[0] || '無効なデータが提供されました。';
260	        return { error: errorMessage };
261	    }
262	    
263	    const { status, last_name, first_name, grade, student_number, generation: directGeneration, team_ids } = parsedData.data;
264	
265	    let finalGeneration: number | null = null;
266	
267	    if (status === 2) { // OB/OG
268	        finalGeneration = directGeneration!;
269	    } else { // Student
270	        const academicYear = getAcademicYear();
271	        finalGeneration = calculateGeneration(status, grade!, academicYear);
272	    }
273	    
274	    if (finalGeneration === null) {
275	        return { error: '期を計算できませんでした。入力内容を確認してください。' };
276	    }
277	
278	    const fullName = (last_name + first_name).replace(/\s/g, '');
279	    
280	    await ensureGenerationRoleExists(finalGeneration);
281	
282	    const discordUsername = user.user_metadata.full_name || null;
283	
284	    const { error: memberInsertError, data: newMember } = await supabase.from('members').insert({
285	        supabase_auth_user_id: user.id,
